"""Five German data-type exercises; render UI from one editable source."""
from pathlib import Path
R=Path(__file__).resolve().parents[1]/'docs'
V='9'
def rng(key,label,value,lo,hi,step=1):return f'<label for="{key}" class="range-label"><span>{label}</span><output aria-hidden="true" id="{key}-value">{value}</output></label><input id="{key}" data-key="{key}" type="range" min="{lo}" max="{hi}" step="{step}" value="{value}">'
def sel(key,label,opts):return f'<label for="{key}">{label}</label><select id="{key}" data-key="{key}">'+''.join(f'<option value="{v}">{t}</option>' for v,t in opts)+'</select>'
def check(key,label):return f'<label class="check"><input type="checkbox" id="{key}" data-key="{key}">{label}</label>'
def group(title,body,modes=''):return f'<div class="control-group"'+(f' data-modes="{modes}"' if modes else '')+f'><h3>{title}</h3>{body}</div>'
modes=[('hue','Farbton'),('form','Form'),('size','Größe'),('value','Helligkeit / Tonwert'),('texture','Textur'),('orientation','Orientierung')]
def alias(fragment,prefix):
 import re
 return re.sub(r'(id|for)="([^"]+)"',lambda m:f'{m[1]}="{prefix}{m[2]}"',fragment)
family=sel('valueFamily','Tonwert-Farbserie',[('gray','Grau'),('blue','Blau'),('green','Grün'),('orange','Orange'),('purple','Violett')])
light_params=family+check('reverseValue','Tonwertfolge umkehren')+rng('lightLow','Dunkler Tonwert L*',25,10,50)+rng('lightHigh','Heller Tonwert L*',83,55,95)
form_params=sel('formSet','Zeichensatz',[('geometric','Kreis · Quadrat · Dreieck · Raute'),('distinct','Kreis · Stern · Kreuz · Y')])
hue_params=sel('palette','Farbserie',[('editorial','Vier Farbtöne'),('bright','Bunte Farbtöne')])
variable_controls=group('1 · Hauptvariable',sel('mode','Visuelle Variable',modes))+group('2 · Parameter',rng('size','Max. Symbolgröße',14,6,22)).replace('class="control-group"','class="control-group" id="common-size"')+group('Farbtöne',hue_params,'hue')+group('Zeichensatz',form_params,'form')+group('Grundform',sel('shape','Zeichen',[('circle','Kreis'),('square','Quadrat')]),'size value texture')+group('Tonwerte',light_params,'value')+group('Muster',rng('texture','Musterabstand',6,4,12),'texture')+group('Drehung',rng('angle','Grundwinkel',0,0,180,15),'orientation')+group('3 · Optionale Kombination',check('combine','Zusätzliche Kodierung ergänzen')+ '<div id="combo-details" class="combo-details" hidden><h4 id="combo-title"></h4><div id="combo-form" hidden>'+alias(form_params,'secondary-')+'</div><div id="combo-hue" hidden>'+alias(hue_params,'secondary-')+'</div><div id="combo-value" hidden>'+alias(light_params,'secondary-')+'</div><div id="combo-size" hidden>'+alias(rng('size','Max. Symbolgröße',14,6,22),'secondary-')+'</div></div>')+group('Kartenbeschriftung',check('names','Ortsnamen zeigen'))
direction_controls=group('1 · Hauptvariable',sel('mode','Visuelle Variable',modes))+group('2 · Parameter',rng('size','Symbolgröße',26,12,44)).replace('class="control-group"','class="control-group" id="common-size"')+group('Orientierung',sel('symbol','Symboltyp',[('circle','Kreis'),('axis','Linie ohne Pfeilspitze'),('arrow','Pfeil')])+check('encode','Nach Messwerten drehen')+sel('ink','Einheitliche Symbolfarbe',[('#285c68','Blau'),('#246e59','Grün'),('#b76133','Orange')])).replace('class="control-group"','class="control-group" data-wind-modes="orientation"')+group('Tonwerte',light_params).replace('class="control-group"','class="control-group" data-wind-modes="value"')+group('Textur',rng('texture','Musterabstand',6,4,12)).replace('class="control-group"','class="control-group" data-wind-modes="texture"')+group('3 · Optionale Kombination',check('speed','Zusätzliche Kodierung ergänzen')+'<div id="wind-combo-details" class="combo-details" hidden><h4>Zusatzvariable: Größe</h4><p class="micro">Die Pfeilfläche zeigt zusätzlich die Windgeschwindigkeit F (m/s).</p>'+rng('speedSize','Max. Pfeillänge',38,18,56)+'</div>')+group('Beschriftung',check('names','Ortsnamen zeigen'))
color_controls=''.join([group('Klassifikation',sel('method','Methode',[('quantile','Quantile'),('equal','Equal Interval'),('jenks','Jenks (Fisher-Jenks)')])+rng('classes','Klassen',7,3,7)),group('Farben',sel('palette','Farbpalette',[('category','Qualitativ · Kategorien'),('warm','Sequenziell · Orange–Rot'),('blue','Sequenziell · Blau'),('viridis','Sequenziell · Viridis'),('diverging','Divergierend · Rot–Blau')])+check('reverse','Reihenfolge umkehren')),group('Lesbarkeit',rng('contrast','Farbkontrast',1,.15,1,.05)+check('gray','Graustufen prüfen')),group('Kartendetails',rng('border','Randlinien',.25,0,.65,.05)+check('names','Ortsnamen zeigen'))])
configs=[
 dict(kind='nominal',file='bertin.html',label='Einrichtungen',title='Visuelle Variablen – Fall 1',sub='Schulen, Kitas, Bibliotheken und Sportzentren in Mainz. Welche Art von Information liegt vor, und wie lässt sie sich verständlich darstellen?',tasks=[('Leserfrage','Wo befinden sich die verschiedenen Einrichtungstypen? Bestimmen Sie die Art der dargestellten Daten.'),('Auswahl','Vergleichen Sie mindestens drei der sechs Variablen. Stellen Sie danach die Parameter Ihrer Wahl ein.'),('Begründung','Welche Information ist jetzt leichter erkennbar? Welche Fehlinterpretationen sind möglich?')]),
 dict(kind='ordinal',file='ordinal.html',label='Rollstuhlzugang',title='Visuelle Variablen – Fall 2',sub='Zugangsangaben zu Mainzer Orten: nicht zugänglich, eingeschränkt und zugänglich. Bestimmen Sie zunächst, welche Art von Information diese Angaben enthalten.',tasks=[('Leserfrage','Wie unterscheiden sich die Zugangsangaben? Was lässt sich darüber sagen, was nicht?'),('Auswahl','Vergleichen Sie mindestens drei visuelle Variablen. Wählen Sie passende Zeichen und Parameter.'),('Begründung','Begründen Sie Ihre Wahl. Fehlende OSM-Angaben dürfen nicht als fehlender Zugang interpretiert werden.')]),
 dict(kind='quantitative',file='quantitativ.html',label='Stadtbevölkerung',title='Visuelle Variablen – Fall 3',sub='Wie viele Menschen leben in Mainz und den umliegenden Städten? Vergleichen Sie Einwohnerzahlen aus derselben amtlichen Quelle und vom selben Stichtag.',tasks=[('Leserfrage','Welche Städte haben viele oder wenige Einwohner? Bestimmen Sie die Art dieser Information.'),('Auswahl','Vergleichen Sie Hauptvariablen. Stellen Sie eine gut lesbare Fassung für den Städtevergleich her.'),('Begründung','Welche Unterschiede lassen sich ablesen? Sind die Relationen zwischen den Zahlen nachvollziehbar?')]),
 dict(kind='direction',file='richtung.html',label='Wind',title='Visuelle Variablen – Fall 4',sub='DWD-Windmessungen im Rhein-Main-Gebiet und Umgebung. DWD beschreibt die Herkunft des Windes; Kartenpfeile zeigen hier die Zielrichtung der Luft.',tasks=[('Leserfrage','Wohin strömt die Luft? Welche Information sollen die Zeichen sichtbar machen?'),('Vergleich','Testen Sie Kreis, ungerichtete Linie und Pfeil. Aktivieren Sie die Drehung nach Messwerten.'),('Begründung','Vergleichen Sie die Lesbarkeit der drei Zeichen. Begründen Sie Ihre Auswahl.')]),
 dict(kind='color',file='farben.html',label='Bevölkerungsraster',title='Klassifikation und Farbe – Fall 5',sub='Bevölkerung in Mainz im 100-m-Gitter. Halten Sie jeweils eine Einstellung konstant und untersuchen Sie, wie Klassengrenzen und Farben das Kartenbild verändern.',tasks=[('Klassifikation','Gleiche Palette, gleiche Klassenanzahl: Vergleichen Sie Equal Interval, Quantile und Jenks.'),('Farben','Klassifikation festhalten: Vergleichen Sie qualitative, sequenzielle und divergierende Farbpaletten.'),('Begründung','Wählen Sie eine Fassung und begründen Sie Klassifikation und Farbwahl. Prüfen Sie auch Graustufen.')])]

def nav(active):return '<header class="topbar"><nav class="nav" aria-label="Hauptnavigation"><a class="brand" href="index.html">Kartographie<span>Lab</span></a><div class="navlinks">'+''.join(f'<a href="{c["file"]}"'+(' aria-current="page"' if c['kind']==active else '')+f'>{i} · {c["label"]}</a>' for i,c in enumerate(configs,1))+'</div></nav></header>'
for i,c in enumerate(configs,1):
 kind=c['kind'];regional=kind in ['ordinal','quantitative','direction'];script='app.mjs' if kind=='color' else 'variables.mjs'
 controls=color_controls if kind=='color' else direction_controls if kind=='direction' else variable_controls
 tasks=''.join(f'<div class="task"><span class="step">{j}</span><div><b>{a}</b><p>{b}</p></div></div>' for j,(a,b) in enumerate(c['tasks'],1))
 cards=''
 for side,title in [('left','Ausgangskarte · unverändert'),('right','Ihre Überarbeitung')]:
  actions='' if side=='left' else '<div class="actions"><button class="btn" id="reset" type="button">↶ Zurücksetzen</button><button class="btn primary" id="export-svg" type="button">SVG ↓</button><button class="btn" id="export-png" type="button">PNG ↓</button></div>'
  cards+=f'<section class="map-card {"original" if side=="left" else "edited"}"><div class="map-toolbar"><div class="map-label"><strong>{title}</strong></div>{actions}</div><svg id="map-{side}" class="map-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 680" role="img" aria-label="{title}"></svg></section>'
 note='OSM-Einrichtungstypen. Kapazitäts- und Qualitätsangaben liegen nicht vor.' if kind=='nominal' else 'Zugangsangaben aus OpenStreetMap, abgerufen am 30.10.2026. Nur benannte, öffentlich genutzte Orte mit explizitem wheelchair=yes, limited oder no innerhalb der Mainzer Stadtgrenze. Keine Angabe bedeutet unbekannt. Die Angaben ersetzen keine Überprüfung vor Ort und beschreiben nicht alle Aspekte von Barrierefreiheit.' if kind=='ordinal' else '20 Städte: Bevölkerung am 31.12.2024 auf Grundlage des Zensus 2022; Gebietsstand 31.03.2026. Quelle: Statistische Ämter des Bundes und der Länder / Destatis, Gemeindeverzeichnis. Gemeindemittelpunkte dienen als Symbolpositionen. Es werden Gemeindegebiete verglichen, keine Ballungsräume.' if kind=='quantitative' else 'Zensus 2022: Personen je vollständiger 100 × 100-m-Zelle; Stichtag 15.05.2022. Fehlende Zellen sind keine gesicherten Nullwerte. Bei gebundenen Werten können Quantile weniger Klassen ergeben.' if kind=='color' else '26 DWD-Stationswerte vom 28.10.2026, 12:00 UTC (13:00 MEZ). F = Stundenmittel der Windgeschwindigkeit (m/s). D = Windherkunft (Grad). Strömungsrichtung = (D + 180°) mod 360°. Keine Interpolation und keine aktuelle Vorhersage. Die recent-Daten sind noch nicht vollständig qualitätsgeprüft.'
 source_link='https://opendata.dwd.de/climate_environment/CDC/observations_germany/climate/hourly/wind/recent/' if kind=='direction' else 'https://www.destatis.de/DE/Themen/Laender-Regionen/Regionales/Gemeindeverzeichnis/_inhalt.html' if kind=='quantitative' else 'https://www.openstreetmap.org/copyright'
 credits='© Deutscher Wetterdienst · CC BY 4.0' if kind=='direction' else '© Statistische Ämter des Bundes und der Länder / Destatis, 2026' if kind=='quantitative' else '© OpenStreetMap contributors · ODbL' if kind!='color' else '© Statistische Ämter des Bundes und der Länder, 2024 · DL-DE/BY-2.0; © OSM contributors'
 footer=f'<footer><p>Hochschule Mainz · Digitale Kartographie · Prof. Dr.-Ing. Yu Feng</p><p>{credits}. Übersichtskarten: Natural Earth, Public Domain.</p><p><a href="{source_link}">Datenquelle</a> · <a href="https://github.com/yfeng-hsm/Karto_HS_Mainz/tree/main/docs/data">Daten und Quellenhinweise</a></p></footer>'

 nextc=configs[i] if i<len(configs) else configs[0]
 html=f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{c['title']} · {c['label']}</title><link rel="stylesheet" href="assets/style.css?v={V}"><script src="assets/d3.min.js" defer></script><script type="module" src="assets/{script}?v={V}"></script></head><body data-lab="{kind}" class="is-loading">{nav(kind)}<main><section class="hero"><h1>{c['title']} · {c['label']}</h1><p>{c['sub']}</p></section><section class="tasks" aria-label="Arbeitsauftrag">{tasks}</section><div id="load-message" role="status">Daten werden geladen …</div><section class="controls-panel" aria-label="Karte gestalten"><div class="controls-heading"><h2>Karte gestalten</h2></div><div class="controls {'color-controls' if kind=='color' else ''}">{controls}</div></section><div class="workspace">{cards}</div><div class="note"><span><b>Daten richtig lesen.</b> {note}</span></div>{'<details class="data-table"></details>' if regional else ''}<section class="discussion"><div><h2>Zeigen und begründen.</h2><p>Melden Sie sich per Handzeichen. Zeigen Sie dem Dozenten beide Karten und begründen Sie Ihre Wahl. Keine Datei-Abgabe erforderlich.</p></div><a href="{nextc['file']}">Weiter: {nextc['label']} →</a></section></main>{footer}</body></html>'''
 (R/c['file']).write_text(html)
cards=''.join(f'<a class="link-card" href="{c["file"]}"><div class="eyebrow">Fall {i}</div><h2>{c["label"]}</h2><p>{c["sub"]}</p><span>Öffnen →</span></a>' for i,c in enumerate(configs,1))
(R/'index.html').write_text(f'<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Digitale Kartographie · Übungen</title><link rel="stylesheet" href="assets/style.css?v={V}"></head><body>{nav("")}<main class="landing"><section class="hero"><h1>Welche Darstellung passt zu den Daten?</h1><p>Fünf kurze Fälle: links die Ausgangskarte, rechts Ihre Überarbeitung. Zuerst die Datenart erkennen, dann eine Hauptvariable wählen und begründen. Farben und Klassifikation werden im fünften Fall getrennt untersucht.</p></section><div class="link-cards">{cards}</div></main></body></html>')
print('Built five case pages and index.html')
